def df_dy(x, y):
    return x**2 + 3

import numpy as np

def loss_partials(w, b, x, y):
    err = w * x + b - y
    dL_dw = np.mean(2 * err * x)
    dL_db = np.mean(2 * err)
    return float(dL_dw), float(dL_db)
